Shader "PostProcess/SSSM"
{
    Properties
    {
        _StepSize ("Step Size", Range(0.1, 2.0)) = 0.5
        _MaxDistance ("Max Distance", Range(1, 200)) = 50.0
        _StepCount ("Step Count", Range(4, 128)) = 32
        _Thickness ("Thickness", Range(0.001, 0.5)) = 0.05
        _BlurScale ("Blur Scale", Range(0.0, 5.0)) = 1.0
    }

    HLSLINCLUDE
    // Unity 6 管线 — 全屏后处理必须使用 Blit.hlsl
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareNormalsTexture.hlsl"
    #include "Packages/com.unity.render-pipelines.core/Runtime/Utilities/Blit.hlsl"
    #include "Assets/Mine/Special/HLSL/HashFunction.hlsl"
    #include "Assets/Mine/Special/HLSL/BlurFunction.hlsl"

    // ── 参数 ──
    CBUFFER_START(UnityPerMaterial)
        float _StepSize;
        float _MaxDistance;
        int   _StepCount;
        float _Thickness;
        float _BlurScale;
    CBUFFER_END
    // DDA 使用 Unity 内置矩阵（与 ComputeWorldSpacePosition / SampleSceneDepth 一致）
    // UNITY_MATRIX_V, UNITY_MATRIX_P — 自动匹配当前相机和图形 API

    // ════════════════════════════════════════════════════════════
    //  Pass 0: DDA 2D 雷步进 — 屏幕空间阴影追踪
    //
    //  核心思路（与 SSR 对称）：
    //     SSR:   沿反射方向步进 → 找第一个表面命中点
    //     SSSM:  沿光源方向步进 → 检查是否有遮挡物
    //
    //  输出：
    //    R: shadow factor（0=完全阴影, 1=完全照亮）
    //    G: 遮挡物平均深度（Eye Space, 保留给未来 PCSS 使用）
    // ════════════════════════════════════════════════════════════
    half4 Frag_SSSM_DDA(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;

        // ── 1. 重建世界坐标 ──
        float rawDepth = SampleSceneDepth(uv);
        float3 positionWS = ComputeWorldSpacePosition(uv, rawDepth, UNITY_MATRIX_I_VP);

        // ── 2. 获取主光源方向（URP 约定：表面→光源） ──
        float3 lightDirWS = GetMainLight().direction;
        float3 viewDirWS  = normalize(_WorldSpaceCameraPos - positionWS);

        // ── 3. DDA Ray 设置（投影到屏幕空间） ──
        float3 startWS = positionWS;
        float3 endWS   = positionWS + lightDirWS * _MaxDistance;

        float3 startVS = mul(UNITY_MATRIX_V, float4(startWS, 1)).xyz;
        float3 endVS   = mul(UNITY_MATRIX_V, float4(endWS, 1)).xyz;

        float  factor = min(1.0, -startVS.z / _MaxDistance);
        endWS = lerp(startWS, endWS, factor);
        endVS = lerp(startVS, endVS, factor);

        float4 startCS = mul(UNITY_MATRIX_P, float4(startVS, 1));
        float4 endCS   = mul(UNITY_MATRIX_P, float4(endVS, 1));

        // 透视校正插值系数: K = 1/w
        float  startK = 1.0 / startCS.w;
        float  endK   = 1.0 / endCS.w;

        // 屏幕空间起始/终点 UV
        float2 startS = (float2(startCS.x, startCS.y * _ProjectionParams.x) * startK) * 0.5 + 0.5;
        float2 endS   = (float2(endCS.x, endCS.y * _ProjectionParams.x) * endK) * 0.5 + 0.5;

        // 透视校正插值: V = viewSpacePos * K
        float3 startV = startVS * startK;
        float3 endV   = endVS * endK;

        // 每步增量
        float  dk = (endK - startK) / _StepCount * _StepSize;
        float2 ds = (endS - startS) / _StepCount * _StepSize;
        float3 dv = (endV - startV) / _StepCount * _StepSize;

        // ── 4. Jitter ──
        float jitter = Hash_Sine21(uv);

        float  K = startK + jitter * dk;
        float2 S = startS + jitter * ds;
        float3 V = startV + jitter * dv;

        // ── 5. 步进与遮挡测试 ──
        float shadow = 1.0;
        float occluderDepthSum = 0.0;
        int   blockerCount = 0;
        float prevDepthDiff = 0.0;

        [loop]
        for (int i = 0; i < _StepCount; i++)
        {
            K += dk;
            S += ds;
            V += dv;

            if (K <= 0.0)
                break;

            if (S.x < 0 || S.x > 1 || S.y < 0 || S.y > 1)
                break;

            float sceneRawDepth = SampleSceneDepth(S);
            float sceneEyeDepth = LinearEyeDepth(sceneRawDepth, _ZBufferParams);
            float linearRayDepth =  - V.z / K;
            float depthDiff = linearRayDepth - sceneEyeDepth;

            bool hitCond1 = (depthDiff > 0.0 && depthDiff < _Thickness);
            bool hitCond2 = (prevDepthDiff < 0.0 && depthDiff > 0.0);
            if (hitCond1)
            {
                shadow = 0.0;
                occluderDepthSum += depthDiff;
                blockerCount++;
                break;
            }
            prevDepthDiff = depthDiff;
        }

        half4 result;
        result.r = shadow;
        result.g = blockerCount > 0 ? occluderDepthSum / blockerCount : 0.0;
        result.ba = half2(0, 1);
        return shadow;
        return result;
    }

    // ════════════════════════════════════════════════════════════
    //  双边保边模糊 — 调用 BlurFunction.hlsl，关键字控制强度与法线
    // ════════════════════════════════════════════════════════════

    half4 Frag_BlurH(Varyings input) : SV_Target
    {
        float2 texelSize = 1.0 / _ScreenParams.xy;
        return BilateralBlurHorizontal(input.texcoord, texelSize, _BlurScale, _BlitTexture, sampler_LinearClamp);
    }

    half4 Frag_BlurV(Varyings input) : SV_Target
    {
        float2 texelSize = 1.0 / _ScreenParams.xy;
        return BilateralBlurVertical(input.texcoord, texelSize, _BlurScale, _BlitTexture, sampler_LinearClamp);
    }
    ENDHLSL

    SubShader
    {
        Tags { "RenderType" = "Opaque" "RenderPipeline" = "UniversalPipeline" }
        Cull Off ZWrite Off ZTest Always

        Pass
        {
            Name "SSSM_RayMarch"
            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag_SSSM_DDA
            ENDHLSL
        }
        Pass
        {
            Name "SSSM_BlurHorizontal"
            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag_BlurH
            #pragma shader_feature _ BLUR_BILATERAL_LOW BLUR_BILATERAL_MEDIUM BLUR_BILATERAL_HIGH
            #pragma shader_feature _ BLUR_BILATERAL_NORMAL
            ENDHLSL
        }
        Pass
        {
            Name "SSSM_BlurVertical"
            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag_BlurV
            #pragma shader_feature _ BLUR_BILATERAL_LOW BLUR_BILATERAL_MEDIUM BLUR_BILATERAL_HIGH
            #pragma shader_feature _ BLUR_BILATERAL_NORMAL
            ENDHLSL
        }
    }
}

Shader "PostProcess/SSC"
{
    Properties
    {
        _BaseColorA ("Base Color", Color) = (1,1,1,1)
        _BaseColorB ("Base Color", Color) = (0,0,0,1)
        _MainTex2D ("Main Texture", 2D) = "white" {}
        _MainTex3D ("Main Texture", 3D) = "white" {}
        _CloudParamA ("Cloud Param A", Vector) = (1,1,1,100)
        _CloudParamB ("Cloud Param B", Vector) = (1,1,1,0.5)
        _Jitter ("Jitter", Float) = 0.5
        _Count ("Count", Int) = 64
    }

    HLSLINCLUDE
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
    #include "Packages/com.unity.render-pipelines.core/Runtime/Utilities/Blit.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
    #include "Assets/Mine/Special/HLSL/DeclareCustomTexture.hlsl"
    #include "Assets/Mine/Special/HLSL/HashFunction.hlsl"

    TEXTURE2D_X(_MainTex2D);
    SAMPLER(sampler_MainTex2D);
    TEXTURE3D(_MainTex3D);
    SAMPLER(sampler_MainTex3D);
    TEXTURE2D_X(_SSCTex);

    CBUFFER_START(UnityPerMaterial)
        float4 _BaseColorA;
        float4 _BaseColorB;
        float4 _CloudParamA;
        float4 _CloudParamB;
        float _Jitter;
        int _Count;
    CBUFFER_END

    float3 ReconstructWorldPos(float2 uv)
    {
        float rawDepth = SampleSceneDepth(uv);
        return ComputeWorldSpacePosition(uv, rawDepth, UNITY_MATRIX_I_VP);
    }

    float Noise(float3 positionWS)
    {
        float noise = 0.0;
        #if defined(SSC_NOISE_TEX2DR)
            float2 uv = positionWS.xz / 256.0;
            noise = _MainTex2D.SampleLevel(sampler_MainTex2D, uv, 0).r;
        #elif defined(SSC_NOISE_TEX2DRG)
            float3 pi = floor(positionWS);
            float3 pf = frac(positionWS);
            float3 uvw = pf * pf * (3.0 - 2.0 * pf);
            float2 uv  = (pi.xz + float2(37.0, 17.0) * pi.y) / 256.0;
            float2 rg = _MainTex2D.SampleLevel(sampler_MainTex2D, uv, 0).rg;
            noise = lerp(rg.x, rg.y, uvw.y / 10);
        #elif defined(SSC_NOISE_TEX3DXYZ)
            float3 uvw = positionWS / 256.0;
            noise = _MainTex3D.SampleLevel(sampler_MainTex3D, uvw, 0).r;
        #else
            noise = 0.0;
        #endif
        return noise;
    }

    float DensityLOD(float3 positionWS, float3 transform, int lod)
    {
        float scale = transform.x;
        float speed = transform.y;
        float rotation = transform.z * 180 / 3.14;
        float3 direction = float3(cos(rotation), 0, sin(rotation));

        float3 pos = (positionWS + speed * _Time.y * direction) * scale;
        float mid = 0.0;
        float amp = 0.5;
        float low = Noise(pos);
        float high = 0.0;

        static const float mul[4] = {2.02, 2.23, 2.41, 2.62};

        [unroll]
        for (int i = 0; i < lod; i++)
        {
            pos *= mul[i];
            mid += amp * Noise(pos);
            amp *= 0.5;
            high = mid;
        }

        float density = lerp(0, high, low);
        return low;
    }

    float DensityH(float3 positionWS, float3 paramUD)
    {
        float top = paramUD.x;
        float bottom = paramUD.y;
        float thiciness = paramUD.z;
        float height = saturate((positionWS.y - bottom) / (top - bottom));
        float middle = 0.5;

        float density = 1 - abs(height - middle) * 2;
        return pow(density, (1.0 - thiciness + 1e-5));
    }

    float CalculateDensity(float3 positionWS, float3 cloudTrans, float3 paramUD, int lod)
    {
        float density = DensityLOD(positionWS, cloudTrans, lod) * DensityH(positionWS, paramUD);
        if (density < 0.2)
        {
            density = 0.0;
        }
        return density;
    }

    #define RAYMARCH(COUNT, LOD) \
        [loop] \
        for (int i = 0; i < COUNT; i++) \
        { \
            if (tCurrent >= tFar || tCurrent >= tScene) \
            { \
                break; \
            } \
             \
            step = min(step, (tFar - tCurrent)); \
            float3 localPosWS = cameraPosWS + rayDirWS * tCurrent; \
            float3 lightPosWS = localPosWS + lightDirWS * step; \
            float localDensity = CalculateDensity(localPosWS, cloudTrans, paramUD, LOD); \
            float lightDensity = CalculateDensity(lightPosWS, cloudTrans, paramUD, LOD); \
            float3 deltaDensity = saturate(localDensity - lightDensity); \
             \
            Diffuse += step * deltaDensity * (1 - Diffuse); \
            Density += step * localDensity * (1 - Density); \
            tCurrent += step; \
        } \

    half4 Frag_SSC(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float3 positionWS = ReconstructWorldPos(uv);
        float3 cameraPosWS = GetCameraPositionWS();

        float  cloudHeight = _CloudParamA.w;
        float3 cloudSize = _CloudParamB.xyz;
        float3 cloudPosWS = float3(0, cloudHeight, 0);

        float3 rayLenWS = positionWS - cameraPosWS;
        float3 rayDirWS = normalize(rayLenWS);
        float3 invDirWS = 1.0 / rayDirWS;

        float3 tMin = (cloudPosWS - cloudSize * 0.5 - cameraPosWS) * invDirWS;
        float3 tMax = (cloudPosWS + cloudSize * 0.5 - cameraPosWS) * invDirWS;

        float3 t1 = min(tMin, tMax);
        float3 t2 = max(tMin, tMax);

        float tScene = dot(rayLenWS, rayDirWS);
        float tNear = max(max(t1.x, t1.y), t1.z);
        float tFar = min(min(t2.x, t2.y), t2.z);

        if (tNear > tFar || tFar < 0.0)
        {
            return 0;
        }

        if (tScene < tNear)
        {
            return 0;
        }

        int Count = 32;
        #if defined(SSC_RAY_COUNT_64)
            Count = 64;
        #elif defined(SSC_RAY_COUNT_128)
            Count = 128;
        #elif defined(SSC_RAY_COUNT_256)
            Count = 256;
        #else
            Count = 32;
        #endif

        float jitter = Hash_Sine21(uv);
        float step = (tFar - tNear) / Count;
        float tCurrent = max(tNear, 0.0) + jitter * step * _Jitter;

        Light mainLight = GetMainLight();
        float3 lightDirWS = mainLight.direction;

        float3 cloudTrans = _CloudParamA.xyz;
        float  cloudThick = _CloudParamB.w;
        float  cloudTop    = cloudPosWS.y + cloudSize.y * 0.5;
        float  cloudBottom = cloudPosWS.y - cloudSize.y * 0.5;
        float3 paramUD = float3(cloudTop, cloudBottom, cloudThick);

        float Diffuse = 0.0;
        float Density = 0.0;

        int CountLOD = Count / 4;
        RAYMARCH(CountLOD, 4);
        RAYMARCH(CountLOD, 3);
        RAYMARCH(CountLOD, 2);
        RAYMARCH(CountLOD, 1);

        // Diffuse /= Count;
        // Density /= Count;

        float4 baseColor = lerp(_BaseColorB, _BaseColorA, Density);
        float4 Color = float4(baseColor.rgb, Density);
        return Color;
    }
    #undef RAYMARCH

    half4 Frag_Composite(Varyings input) : SV_Target
    {
        float4 cloudColor = SampleCustomTexture(_SSCTex, sampler_LinearClamp, input.texcoord);
        float4 sceneColor = SAMPLE_TEXTURE2D_X(_BlitTexture, sampler_LinearClamp, input.texcoord);
        return lerp(sceneColor, cloudColor, cloudColor.a);
    }
    ENDHLSL

    SubShader
    {
        Tags { "RenderType"="Transparent" "Queue"="Transparent" }
        LOD 100
        Blend One Zero

        Pass
        {
            Name "SSC"

            HLSLPROGRAM
            #pragma multi_compile _ SSC_NOISE_TEX2DR SSC_NOISE_TEX2DRG SSC_NOISE_TEX3DXYZ
            #pragma multi_compile _ SSC_RAY_COUNT_64 SSC_RAY_COUNT_128 SSC_RAY_COUNT_256
            #pragma target 2.0
            #pragma vertex Vert
            #pragma fragment Frag_SSC
            ENDHLSL
        }

        Pass
        {
            Name "Composite"

            HLSLPROGRAM
            #pragma target 2.0
            #pragma vertex Vert
            #pragma fragment Frag_Composite
            ENDHLSL
        }
    }
}

Shader "PostProcess/SSL"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" { }
    }

    HLSLINCLUDE
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
    #include "Packages/com.unity.render-pipelines.core/Runtime/Utilities/Blit.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
    #include "Assets/Mine/Special/HLSL/HashFunction.hlsl"
    #include "Assets/Mine/Special/HLSL/BlurFunction.hlsl"

    // ════════════════════════════════════════════════════════════
    //  共享 Uniforms
    // ════════════════════════════════════════════════════════════

    int   _MaxSteps;
    float _MaxDistance;
    float _Intensity;
    float _SSLScale;
    float _BlurScale;
    float _JitterScale;

    TEXTURE2D_X(_SSLTex);

    // ════════════════════════════════════════════════════════════
    //  RAY3D — 屏幕空间光体积步进（原 SSL 方法）
    // ════════════════════════════════════════════════════════════

    // 深度重建世界坐标
    float3 ReconstructWorldPos(float2 uv)
    {
        float rawDepth = SampleSceneDepth(uv);
        return ComputeWorldSpacePosition(uv, rawDepth, UNITY_MATRIX_I_VP);
    }

    // 世界坐标采样阴影图
    float SampleShadow(float3 positionWS)
    {
        float4 shadowCoord = TransformWorldToShadowCoord(positionWS);
        return SAMPLE_TEXTURE2D_SHADOW(
            _MainLightShadowmapTexture,
            sampler_MainLightShadowmapTexture,
            shadowCoord);
    }

    float HG(float cosTheta, float g)
    {
        return (1 - g * g) / pow(1 + g * g - 2 * g * cosTheta, 1.5);
    }

    // 屏幕空间光体积步进 — 沿视线累积阴影光照（SSL_LIGHT）/ 深度密度（SSL_FOG）
    float SSL(
        float3 cameraPos,
        float3 lightDir,
        float3 worldPosFromDepth,
        int    maxSteps,
        float  maxDistance,
        float2 uv
    )
    {
        float3 rayVec  = worldPosFromDepth - cameraPos;
        float3 rayDir  = normalize(rayVec);
        float  rayLen  = clamp(length(rayVec), 0.0, maxDistance);

        float  stepSize   = rayLen / maxSteps;
        float3 jitter     = Hash_Sine21(uv);
        float3 currentPos = cameraPos + rayDir * (stepSize * jitter.x * _JitterScale);
        float  density = 0.0;

        #if defined(SSL_LIGHT)
        [loop]
        for (int i = 0; i < maxSteps; i++)
        {
            if (length(currentPos - cameraPos) > maxDistance)
            {
                break;
            }
            float lighting = SampleShadow(currentPos);
            float phase = HG(dot(rayDir, lightDir), _SSLScale);
            lighting *= saturate(phase);
            currentPos += rayDir * stepSize;
            density += stepSize * lighting;
        }
        #elif defined(SSL_FOG)
        [loop]
        for (int i = 0; i < maxSteps; i++)
        {
            if (length(currentPos - cameraPos) > maxDistance)
            {
                break;
            }
            currentPos += rayDir * stepSize;
            density += stepSize;
        }
        #else
        density = 0.0;
        #endif

        density /= maxSteps;
        return density;
    }

    // ════════════════════════════════════════════════════════════
    //  RBR2D — 全屏径向模糊（样本 Full Scene Radial Blur 改造）
    //
    //  blur 中心 = 主平行光方向在屏幕上的投影焦点，取代样本的
    //  屏幕中心 + 假光偏移；模糊方向即平行光方向
    // ════════════════════════════════════════════════════════════

    // 平行光方向 → 屏幕空间焦点 UV（沿光方向取远点投影）
    float2 GetLightFocusUV()
    {
        Light mainLight = GetMainLight();
        float3 lightPosFar = GetCameraPositionWS() + mainLight.direction * _MaxDistance;
        float4 clip = mul(UNITY_MATRIX_VP, float4(lightPosFar, 1.0));
        if (clip.w <= 0.0) return float2(0.5, 0.5);   // 光在相机背后 → 回退屏幕中心
        float2 focus = clip.xy / clip.w * 0.5 + 0.5;
        focus.y = 1.0 - focus.y;
        return clamp(focus, -0.5, 1.5);               // 允许离屏焦点，限制极端值
    }

    // 2x1 hash — 采样抖动去 banding
    float hash21(float2 p)
    {
        return frac(sin(dot(p, float2(41.0, 289.0))) * 45758.5453);
    }

    // ════════════════════════════════════════════════════════════
    //  Pass 0 入口 — 关键字分发到 RAY3D / RBR2D
    // ════════════════════════════════════════════════════════════

    half4 Frag_RAY3D(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        Light mainLight = GetMainLight();
        float3 lightDirWS  = mainLight.direction;
        float3 cameraPosWS = GetCameraPositionWS();
        float3 positionWS  = ReconstructWorldPos(uv);

        float density = SSL(
            cameraPosWS,
            lightDirWS,
            positionWS,
            _MaxSteps,
            _MaxDistance,
            uv
        );

        float sslLight = density * _Intensity;
        float3 sslColor = mainLight.color * sslLight;
        return float4(sslColor, 1.0);
    }

    // 径向模糊采样累积 — 沿 (uv → 光焦点) 方向递减加权
    half4 Frag_RBR2D(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float2 focusUV = GetLightFocusUV();

        float  decay   = 0.97;    // 向外辐射的权重衰减
        float  density = 0.5;     // 采样密度（控制 blur 扩散范围）
        float  weight  = 0.1;     // 采样权重
        const float SAMPLES = 24.0;

        // blur 方向向量：像素 → 光焦点（即平行光方向）
        float2 tuv  = uv - focusUV;
        float2 dTuv = tuv * density / SAMPLES;

        half4 col = SAMPLE_TEXTURE2D_X(_BlitTexture, sampler_LinearClamp, uv) * 0.25;

        // 抖动去 banding
        uv += dTuv * (hash21(uv + frac(_Time.y)) * 2.0 - 1.0);

        [loop]
        for (float i = 0.0; i < SAMPLES; i++)
        {
            uv -= dTuv;
            col += SAMPLE_TEXTURE2D_X(_BlitTexture, sampler_LinearClamp, uv) * weight;
            weight *= decay;
        }

        // 焦点聚光收尾
        col *= 1.0 - dot(tuv, tuv) * 0.75;
        return col;
    }

    half4 Frag(Varyings input) : SV_Target
    {
        #if defined(SSL_RBR2D)
            return Frag_RBR2D(input);
        #else
            return Frag_RAY3D(input);
        #endif
    }

    // ════════════════════════════════════════════════════════════
    //  模糊 Pass 入口 — BlurFunction.hlsl 双向高斯
    // ════════════════════════════════════════════════════════════

    half4 Frag_BlurHorizontal(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float2 texelSize = float2(1.0 / _ScreenParams.x, 1.0 / _ScreenParams.y);
        return BlurHorizontal(uv, texelSize, _BlurScale, _BlitTexture, sampler_LinearClamp);
    }

    half4 Frag_BlurVertical(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float2 texelSize = float2(1.0 / _ScreenParams.x, 1.0 / _ScreenParams.y);
        return BlurVertical(uv, texelSize, _BlurScale, _BlitTexture, sampler_LinearClamp);
    }

    // ════════════════════════════════════════════════════════════
    //  合成 Pass — RBR2D: lerp 模糊场景 / RAY3D: 加法体积光
    // ════════════════════════════════════════════════════════════

    half4 Frag_Mix(Varyings input) : SV_Target
    {
        half4 mainColor = SAMPLE_TEXTURE2D_X(_BlitTexture, sampler_LinearClamp, input.texcoord);
        half4 sslColor  = SAMPLE_TEXTURE2D_X(_SSLTex, sampler_LinearClamp, input.texcoord);
        #if defined(SSL_RBR2D)
            return lerp(mainColor, sslColor, _Intensity);
        #else
            return mainColor + sslColor;
        #endif
    }
    ENDHLSL

    SubShader
    {
        Tags
        {
            "RenderPipeline" = "UniversalPipeline"
            "RenderType" = "Opaque"
        }

        Cull Off
        ZWrite Off
        ZTest Always
        Blend One Zero

        Pass
        {
            Name "SSL_Raymarch"

            HLSLPROGRAM
            #pragma target 2.0
            #pragma multi_compile _ SSL_RBR2D SSL_RAY3D
            #pragma multi_compile _ SSL_FOG SSL_LIGHT
            #pragma vertex Vert
            #pragma fragment Frag
            ENDHLSL
        }

        Pass
        {
            Name "SSL_BlurHorizontal"

            HLSLPROGRAM
            #pragma target 2.0
            #pragma vertex Vert
            #pragma fragment Frag_BlurHorizontal
            ENDHLSL
        }

        Pass
        {
            Name "SSL_BlurVertical"

            HLSLPROGRAM
            #pragma target 2.0
            #pragma vertex Vert
            #pragma fragment Frag_BlurVertical
            ENDHLSL
        }

        Pass
        {
            Name "SSL_Mix"

            HLSLPROGRAM
            #pragma target 2.0
            #pragma multi_compile _ SSL_RBR2D SSL_RAY3D
            #pragma vertex Vert
            #pragma fragment Frag_Mix
            ENDHLSL
        }
    }

    FallBack Off
}

Assets/Mine/Shaders/PostProcess/PCSS/PCS:
// ════════════════════════════════════════════════════════════
//  PCSS Compute Shader — 共享声明与工具函数
//  被 PCSS.compute #include 使用
// ════════════════════════════════════════════════════════════

// 时域累积共享库（跨效果横切，Assets 全路径）
#include "Assets/Mine/Special/HLSL/TemporalFunction.hlsl"
#include "Assets/Mine/Special/HLSL/HashFunction.hlsl"

// ── 质量档位（编译期固定采样数，编译器可展开循环）──
// 未定义 = High: 32, PCSS_MEDIUM: 16, PCSS_LOW: 8
// 关键词由 PCSSFeature 按性能档位下发（PerformanceTier.samples）
#if defined(PCSS_LOW)
    #define BLOCKER_SAMPLES 8
    #define PCF_SAMPLES 8
#elif defined(PCSS_MEDIUM)
    #define BLOCKER_SAMPLES 16
    #define PCF_SAMPLES 16
#else
    #define BLOCKER_SAMPLES 32
    #define PCF_SAMPLES 32
#endif

#define NUMTHREAD_X 8
#define NUMTHREAD_Y 8

// ── 输入纹理 ──
Texture2D<float>   _CameraDepthTexture;
Texture2D<float4>  _CameraNormalsTexture;
Texture2D<float>   _PCSS_ShadowCacheTex;

// ── 输出 ──
RWTexture2D<float4> _PCSS_SoftShadow;

// ── 双边模糊 I/O ──
Texture2D<float4>   _PCSS_BlurInput;
RWTexture2D<float4> _PCSS_BlurOutput;
float _BlurScale;

// ── 时域累积 I/O ──
// _PCSS_CurrentTex 是 _PCSS_SoftShadow 的 SRV 视图（同一次 dispatch 内
// 不可既是 SRV 又是 UAV，故当帧信号单独绑定一份只读句柄）
Texture2D<float4>   _PCSS_CurrentTex;
Texture2D<float4>   _PCSS_HistoryInput;
RWTexture2D<float4> _PCSS_TemporalOut;
RWTexture2D<float4> _PCSS_HistoryOutput;
float4x4 _PrevViewProj;
