        float2(0, -1), float2(0, 1)
    };

    static const float2 UVoffsetsSobel[8] = {
        float2(-1, -1), float2(0, -1), float2(1, -1),
        float2(-1,  0),                float2(1,  0),
        float2(-1,  1), float2(0,  1), float2(1,  1)
    };

    float SampleDepth(float2 uv)
    {
