#ifndef RAINDROP_INCLUDED
#define RAINDROP_INCLUDED

// ============================================================================
//  RainDrop.hlsl — 程序化雨滴工具库
//  ============================================================================
//  依赖: Core.hlsl (Unity URP)
//  使用: #include "Assets/Mine/Special/Shaders/RainDrop.hlsl"
//  ============================================================================

// ---- 数据结构 ----

struct DropShapeResult
{
    float  mask;
    float  normDist;
    float2 radialDir;
    float2 offset;
};

struct DropLayerResult
{
    float2 uv;
    float2 offset;
    float  mask;
    float  normDist;
    float2 radialDir;
};

// ---- 工具函数 ----

float2 Hash2D(float2 p)
{
    float3 p3 = frac(float3(p.xyx) * 0.1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return frac(float2((p3.x + p3.y) * p3.z, (p3.x + p3.z) * p3.y));
}

float Saw(float b, float t)
{
    return smoothstep(0.0, b, t) * smoothstep(1.0, b, t);
}

// ---- 空间变换 ----

float2 RemapUV(float2 objectUV, float2 gridScale, float time, float speed, float wiggle)
{
    float2 uv = objectUV;
    float  rand = sin(uv.y * 6.2831) * 0.25 + 1;
    uv.x += sin(uv.y * 6.2831 * rand) * 0.02;
    uv.x += sin(uv.x * 6.2831 * rand) * 0.05;

    float2 gridUV = uv * gridScale;
    float colIdx = floor(gridUV.x);
    float colR = Hash2D(float2(colIdx, 137.0)).x;
    time *= speed;
    uv.y *= sin(uv.y * colR * 6.2831 * 0.25) * 0.5 + 0.5;
    uv.y += time * colR;

    float slipCycle = time * 0.12 + colR * 2.0;
    float slipSlope = pow(frac(slipCycle), 4.0);
    float slipOffset = (floor(slipCycle) + slipSlope) * 0.4 * wiggle;
    uv.y += slipOffset;

    return uv;
}

float2 RemapGridUV(float2 st, float2 rand, float dropLen, float aspect, float size)
{
    float2 uv = st - float2(0.5, 0.5);
    float scale = (rand.x * 0.4 + 1.2) / max(size, 1e-6);

    uv.y *= lerp(aspect, 1.0 / scale, dropLen);
    uv *= scale;
    uv += rand;

    return uv;
}

// ---- 形状采样 ----

DropShapeResult DropShape(float2 shapeUV, float intensity, float refraction, bool facingCamera)
{
    DropShapeResult r = (DropShapeResult)0;

    float dx = shapeUV.x;
    float dy = shapeUV.y;

    float dist;
    if (dy > 0.0)
    {
        float taper = 1.0 - saturate(dy);
        float rx = max(taper, 0.01);
        dist = length(float2(dx / rx, dy));
    }
    else
    {
        dist = length(float2(dx, dy));
    }

    r.mask = (1.0 - smoothstep(0.7, 1.0, dist)) * intensity;
    r.normDist = saturate(dist);
    r.radialDir = length(shapeUV) > 1e-6 ? normalize(shapeUV) : float2(0.0, 1.0);

    float t = r.normDist;
    if (facingCamera)
    {
        float lens = (t - 0.45) * 2.5;
        r.offset = r.radialDir * lens * refraction * r.mask;
    }
    else
    {
        float lens = t * (1.0 - t) * 4.0;
        r.offset = r.radialDir * lens * refraction * r.mask;
    }

    return r;
}

// ---- 编排层 ----

struct DropConfig
{
    float  speed;
    float  wiggle;
    float  range;
    float2 gridScale;
    float  coverage;
    float  dropLen;
    float  dropSize;
    float  dropFacing;
    float  sawSpeed;
    float  sawSmooth;
    float  refraction;
    bool   applyRemap;
};

DropLayerResult DropLayer(float2 objectUV, float time, DropConfig cfg)
{
    DropLayerResult result = (DropLayerResult)0;

    float aspect = cfg.gridScale.x / cfg.gridScale.y;
    float2 uv = cfg.applyRemap ? RemapUV(objectUV, cfg.gridScale, time, cfg.speed, cfg.wiggle) : objectUV;

    float2 gridUV = uv * cfg.gridScale;
    float2 id = floor(gridUV);
    float2 st = frac(gridUV);
    float2 rand = Hash2D(id);
    result.uv = st;

    if (rand.x >= cfg.coverage)
        return result;

    float ti = frac(time * cfg.sawSpeed + rand.y * 0.618 + rand.x * 0.382);
    float intensity = Saw(cfg.sawSmooth, ti);
    rand = (rand - 0.5) * cfg.range;
    bool facing = cfg.dropFacing > 0.5;
    float2 shapeUV = RemapGridUV(st, rand, cfg.dropLen, aspect, cfg.dropSize);
    DropShapeResult drop = DropShape(shapeUV, intensity, cfg.refraction, facing);

    result.mask   = drop.mask;
    result.offset = drop.offset;

    if (drop.mask > 0.0)
    {
        result.normDist  = drop.normDist;
        result.radialDir = drop.radialDir;
    }

    return result;
}

// ---- 层级混合 ----

DropLayerResult BlendLayer(DropLayerResult a, DropLayerResult b)
{
    float wa = a.mask;
    float wb = b.mask;
    float total = wa + wb;

    DropLayerResult r;
    r.mask = max(wa, wb);

    if (total > 0.001)
    {
        r.offset    = (a.offset    * wa + b.offset    * wb) / total;
        r.normDist  = (a.normDist  * wa + b.normDist  * wb) / total;
        r.radialDir = normalize(a.radialDir * wa + b.radialDir * wb);
    }
    else
    {
        r = (DropLayerResult)0;
    }

    r.uv = wa > wb ? a.uv : b.uv;
    return r;
}

#endif

Shader "Render/RainDrops"
{
    Properties
    {
        [Header(Drop Layer)]
        [Space]
        _Columns ("Columns", Range(4, 40)) = 12
        _Rows ("Rows", Range(1, 6)) = 2
        _Coverage ("Coverage", Range(0.0, 1.0)) = 0.85
        _DropSize ("Drop Size", Range(0.0, 0.5)) = 0.35

        [Header(Motion)]
        [Space]
        _FlowSpeed ("Flow Speed", Range(0.0, 1.0)) = 0.2
        _Wiggle ("Wiggle Strength", Range(0.0, 1.0)) = 0.5

        [Header(Shape)]
        [Space]
        _DropLength ("Drop Length", Range(0.0, 1.0)) = 0.6
        [Toggle] _DropFacing ("Camera Facing", Float) = 0

        [Header(Refraction)]
        [Space]
        _Refraction ("Refraction Strength", Range(0.0, 0.06)) = 0.025

        [Header(Wetness)]
        [Space]
        _Darken ("Darken", Range(0.0, 0.5)) = 0.15
        _Desaturate ("Desaturate", Range(0.0, 1.0)) = 0.25

        [Header(Specular)]
        [Space]
        _SpecIntensity ("Intensity", Range(0.0, 5.0)) = 1.2
        _Roughness ("Roughness", Range(0.0, 1.0)) = 0.15
        _NormalTilt ("Normal Tilt", Range(0.0, 1.0)) = 0.4
    }

    HLSLINCLUDE

    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareOpaqueTexture.hlsl"
    #include "Assets/Mine/Special/HLSL/NPRFunction.hlsl"
    #include "RainDrop.hlsl"

    CBUFFER_START(UnityPerMaterial)
        float _Columns;
        float _Rows;
        float _Coverage;
        float _DropSize;
        float _FlowSpeed;
        float _Wiggle;
        float _DropLength;
        float _DropFacing;
        float _Refraction;
        float _Darken;
        float _Desaturate;
        float _SpecIntensity;
        float _Roughness;
        float _NormalTilt;
    CBUFFER_END

    struct Attributes
    {
        float4 positionOS : POSITION;
        float3 normalOS   : NORMAL;
        float4 tangentOS  : TANGENT;
        float2 uv         : TEXCOORD0;
    };

    struct Varyings
    {
        float4 positionCS : SV_POSITION;
        float2 uv         : TEXCOORD0;
        float4 screenPos  : TEXCOORD1;
        float3 normalWS   : TEXCOORD2;
        float4 tangentWS  : TEXCOORD3;
        float3 positionWS : TEXCOORD4;
    };

    Varyings Vert(Attributes input)
    {
        Varyings output;
        output.positionCS = TransformObjectToHClip(input.positionOS.xyz);
        output.uv         = input.uv;
        output.screenPos  = ComputeScreenPos(output.positionCS);

        VertexNormalInputs nrm = GetVertexNormalInputs(input.normalOS, input.tangentOS);
        output.normalWS   = nrm.normalWS;
        output.tangentWS  = float4(nrm.tangentWS, input.tangentOS.w);
        output.positionWS = TransformObjectToWorld(input.positionOS.xyz);
        return output;
    }

    float4 Frag(Varyings input) : SV_Target
    {
        float2 screenUV = input.screenPos.xy / input.screenPos.w;

        float cols = _Columns;
        float rows = _Rows;

        DropLayerResult drops = (DropLayerResult)0;

        // 流动水滴
        DropConfig mainCfg = { _FlowSpeed, _Wiggle, 0.4,
            float2(cols, rows), _Coverage, _DropLength, _DropSize, _DropFacing,
            0.1, 0.85, _Refraction, true };
        drops = BlendLayer(drops, DropLayer(input.uv, _Time.y, mainCfg));

        // 静态小雨滴
        DropConfig smallCfg = { _FlowSpeed * 0.01, _Wiggle, 2,
            float2(cols, rows * 6), _Coverage * 0.2, 0.5, _DropSize, _DropFacing,
            0.2, 0.75, _Refraction, true };
        drops = BlendLayer(drops, DropLayer(input.uv, _Time.y, smallCfg));

        // 细长水痕
        DropConfig streakCfg = { _FlowSpeed * 0.01, _Wiggle, 0,
            float2(cols * 0.5, rows * 0.75), _Coverage * 0.5, 0.99, _DropSize * 0.5, _DropFacing,
            0.03, 0.9, _Refraction * 0.2, true };
        drops = BlendLayer(drops, DropLayer(input.uv, _Time.y, streakCfg));

        float3 sceneColor = SampleSceneColor(screenUV + drops.offset).rgb;
        float3 wetColor = sceneColor * (1.0 - _Darken * drops.mask);
        float luma = dot(wetColor, float3(0.299, 0.587, 0.114));
        wetColor = lerp(wetColor, luma.xxx, _Desaturate * drops.mask);
        // return float4(drops.uv, drops.mask, 1);
        if (drops.mask > 0.001 && _SpecIntensity > 0.0)
        {
            Light light = GetMainLight();
            float3 viewDir  = normalize(GetCameraPositionWS() - input.positionWS);
            float3 tangent  = input.tangentWS.xyz;
            float3 bitangent = cross(input.normalWS, tangent) * input.tangentWS.w;

            float tilt = drops.normDist * _NormalTilt;
            float3 pert = tangent * drops.radialDir.x * tilt
                        + bitangent * drops.radialDir.y * tilt;
            float3 dropNormal = normalize(input.normalWS + pert);

            float smoothness = 1.0 - _Roughness;
            float spec = SpecularBlinnPhong(dropNormal, light.direction, viewDir, smoothness);
            wetColor += spec * _SpecIntensity * drops.mask;
        }

        return float4(wetColor, 1.0);
    }

    ENDHLSL

    SubShader
    {
        Tags
        {
            "RenderType" = "Transparent"
            "RenderPipeline" = "UniversalPipeline"
            "Queue" = "Transparent"
        }

        Blend SrcAlpha OneMinusSrcAlpha
        ZWrite Off
        Cull Back

        Pass
        {
            Name "RainDrops"
            Tags { "LightMode" = "UniversalForward" }

            HLSLPROGRAM
            #pragma vertex Vert
            #pragma fragment Frag
            ENDHLSL
        }
    }
}

