// ═══════════════════════════════════════════════════════════════
//  SpecularGI Sampling — reflection rays and cubemap radiance.
// ═══════════════════════════════════════════════════════════════
#ifndef SPECULAR_GI_SAMPLING_INCLUDED
#define SPECULAR_GI_SAMPLING_INCLUDED

float2 SpecularGI_Hash22(float2 value)
{
    float3 p = frac(float3(value.xyx) * float3(0.1031, 0.1030, 0.0973));
    p += dot(p, p.yzx + 33.33);
    return frac((p.xx + p.yz) * p.zy);
}

float3 SpecularGI_SampleGGXVNDF(float2 randomValue, float roughness, float3 normalWS, float3 viewToCameraWS)
{
    float3 tangentWS = abs(normalWS.y) < 0.999
        ? normalize(cross(float3(0.0, 1.0, 0.0), normalWS))
        : float3(1.0, 0.0, 0.0);
    float3 bitangentWS = cross(normalWS, tangentWS);
    float3 viewLocal = float3(
        dot(viewToCameraWS, tangentWS),
        dot(viewToCameraWS, bitangentWS),
        dot(viewToCameraWS, normalWS));

    float alpha = max(roughness * roughness, 0.0025);
    float3 viewHemisphere = normalize(float3(alpha * viewLocal.xy, max(viewLocal.z, 0.0001)));
    float lensSquared = dot(viewHemisphere.xy, viewHemisphere.xy);
    float3 tangent1 = lensSquared > 0.0001
        ? float3(-viewHemisphere.y, viewHemisphere.x, 0.0) * rsqrt(lensSquared)
        : float3(1.0, 0.0, 0.0);
    float3 tangent2 = cross(viewHemisphere, tangent1);

    float radius = sqrt(randomValue.x);
    float phi = TWO_PI * randomValue.y;
    float sampleX = radius * cos(phi);
    float sampleY = radius * sin(phi);
    float interpolation = 0.5 * (1.0 + viewHemisphere.z);
    sampleY = lerp(sqrt(saturate(1.0 - sampleX * sampleX)), sampleY, interpolation);

    float3 normalHemisphere = sampleX * tangent1
        + sampleY * tangent2
        + sqrt(saturate(1.0 - sampleX * sampleX - sampleY * sampleY)) * viewHemisphere;
    float3 halfLocal = normalize(float3(alpha * normalHemisphere.xy, max(normalHemisphere.z, 0.0)));
    return normalize(
        tangentWS * halfLocal.x
        + bitangentWS * halfLocal.y
        + normalWS * halfLocal.z);
}

float3 SpecularGI_CreateRayDirection(float2 uv, float3 normalWS, float3 viewDirectionWS)
{
    if (_Roughness <= 0.02)
        return normalize(reflect(viewDirectionWS, normalWS));

    float2 randomValue = SpecularGI_Hash22(uv * _ScreenParams.xy + _FrameIndex * float2(0.754877, 0.569840));
    float3 halfVectorWS = SpecularGI_SampleGGXVNDF(randomValue, _Roughness, normalWS, -viewDirectionWS);
    return normalize(reflect(viewDirectionWS, halfVectorWS));
}

float3 SpecularGI_SampleSky(float3 directionWS)
{
    float mipLevel = saturate(_Roughness) * max(_SkyMaxMip, 0.0);
    return SAMPLE_TEXTURECUBE_LOD(_SkyCubemap, sampler_SkyCubemap, directionWS, mipLevel).rgb;
}

#endif

// ═══════════════════════════════════════════════════════════════
//  SpecularGI — SSSR screen trace with cubemap fallback.
// ═══════════════════════════════════════════════════════════════
Shader "PostProcess/SpecularGI"
{
    Properties
    {
        _SkyCubemap ("Sky Cubemap", Cube) = "black" {}
    }

    HLSLINCLUDE
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
    #include "Packages/com.unity.render-pipelines.core/Runtime/Utilities/Blit.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareDepthTexture.hlsl"
    #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/DeclareNormalsTexture.hlsl"

    TEXTURECUBE(_SkyCubemap);
    SAMPLER(sampler_SkyCubemap);
    TEXTURE2D_X(_SpecularGITexture);

    CBUFFER_START(UnityPerMaterial)
        float4 _TraceParams;
        float _Roughness;
        float _Intensity;
        float _SkyMaxMip;
        float _SpatialRadius;
        float _FrameIndex;
        float _DebugMode;
    CBUFFER_END

    #include "Assets/Mine/Shaders/PostProcess/SSGI/ScreenSpaceTrace.hlsl"
    #include "Assets/Mine/Shaders/PostProcess/SSGI/SpecularGI/SpecularGISampling.hlsl"
    #include "Assets/Mine/Shaders/PostProcess/SSGI/SpecularGI/SpecularGITrace.hlsl"
    #include "Assets/Mine/Shaders/PostProcess/SSGI/SpecularGI/SpecularGIFilter.hlsl"

    // ════════════════════════════════════════════════════════════
    //  Trace — screen hit first, cubemap on misses and low-confidence edges
    // ════════════════════════════════════════════════════════════
    half4 Frag_Trace(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float rawDepth = SST_SampleDepth(uv);
        if (!SST_IsSurface(rawDepth))
            return 0.0;

        float3 positionWS = SST_WorldPosition(uv, rawDepth);
        float3 normalWS = normalize(SampleSceneNormals(uv));
        float3 viewDirectionWS = -GetWorldSpaceNormalizeViewDir(positionWS);
        if (dot(normalWS, -viewDirectionWS) <= 0.0)
            return 0.0;

        float3 rayDirectionWS = SpecularGI_CreateRayDirection(uv, normalWS, viewDirectionWS);
        if (dot(normalWS, rayDirectionWS) <= 0.0001)
            rayDirectionWS = normalize(reflect(viewDirectionWS, normalWS));

        float3 originWS = positionWS + normalWS * _TraceParams.z;
        SpecularTraceResult screenResult = SpecularGI_TraceScreen(
            originWS,
            rayDirectionWS,
            _TraceParams.x,
            _TraceParams.y,
            (int)_TraceParams.w);

        float3 screenRadiance = screenResult.valid
            ? SAMPLE_TEXTURE2D_X_LOD(_BlitTexture, sampler_LinearClamp, screenResult.uv, 0).rgb
            : 0.0;
        float screenConfidence = screenResult.valid ? screenResult.confidence : 0.0;

        float3 skyRadiance = SpecularGI_SampleSky(rayDirectionWS);
        float3 radiance = lerp(skyRadiance, screenRadiance, screenConfidence);
        return float4(radiance, screenConfidence);
    }

    // ════════════════════════════════════════════════════════════
    //  Resolve stages — spatial geometry weights then temporal history
    // ════════════════════════════════════════════════════════════
    half4 Frag_Spatial(Varyings input) : SV_Target
    {
        return SpecularGI_SpatialResolve(input.texcoord);
    }

    half4 Frag_Upsample(Varyings input) : SV_Target
    {
        return SpecularGI_Upsample(input.texcoord);
    }

    // ════════════════════════════════════════════════════════════
    //  Composite and debug — Fresnel blend or source contribution view
    // ════════════════════════════════════════════════════════════
    half4 Frag_Composite(Varyings input) : SV_Target
    {
        float2 uv = input.texcoord;
        float4 sceneColor = SAMPLE_TEXTURE2D_X_LOD(_BlitTexture, sampler_LinearClamp, uv, 0);
        float rawDepth = SST_SampleDepth(uv);
        if (!SST_IsSurface(rawDepth) || _Intensity <= 0.0)
            return sceneColor;

        float3 positionWS = SST_WorldPosition(uv, rawDepth);
        float3 normalWS = normalize(SampleSceneNormals(uv));
        float3 viewToCameraWS = GetWorldSpaceNormalizeViewDir(positionWS);
        float fresnel = 0.04 + 0.96 * pow(1.0 - saturate(dot(normalWS, viewToCameraWS)), 5.0);
        fresnel *= 1.0 - _Roughness * 0.5;

        float3 reflection = SAMPLE_TEXTURE2D_X_LOD(
            _SpecularGITexture,
            sampler_LinearClamp,
            uv,
            0).rgb;
        sceneColor.rgb = lerp(sceneColor.rgb, reflection, saturate(_Intensity * fresnel));
        return sceneColor;
    }

    half4 Frag_Debug(Varyings input) : SV_Target
    {
        float4 value = SAMPLE_TEXTURE2D_X_LOD(_BlitTexture, sampler_LinearClamp, input.texcoord, 0);
        if (_DebugMode < 0.5)
            return value;
        if (_DebugMode < 1.5)
            return float4(saturate(value.a).xxx, 1.0);
        return float4(saturate(1.0 - value.a).xxx, 1.0);
    }
    ENDHLSL

    SubShader
    {
        Tags { "RenderType" = "Opaque" "RenderPipeline" = "UniversalPipeline" }
        Cull Off
        ZWrite Off
        ZTest Always

        Pass
        {
            Name "Trace"
            HLSLPROGRAM
            #pragma target 3.5
            #pragma vertex Vert
            #pragma fragment Frag_Trace
            ENDHLSL
        }

        Pass
        {
            Name "SpatialResolve"
            HLSLPROGRAM
            #pragma target 3.5
            #pragma vertex Vert
            #pragma fragment Frag_Spatial
            ENDHLSL
        }

        Pass
        {
            Name "Upsample"
            HLSLPROGRAM
            #pragma target 3.5
            #pragma vertex Vert
            #pragma fragment Frag_Upsample
            ENDHLSL
        }

        Pass
        {
            Name "Composite"
            HLSLPROGRAM
            #pragma target 3.5
            #pragma vertex Vert
            #pragma fragment Frag_Composite
            ENDHLSL
        }

        Pass
        {
            Name "Debug"
            HLSLPROGRAM
            #pragma target 3.5
            #pragma vertex Vert
            #pragma fragment Frag_Debug
            ENDHLSL
        }
    }

    FallBack "Hidden/Universal Render Pipeline/FallbackError"
}

